import io as 입출력
import functools
from math import sqrt

class 계산기:
    pass

def 그대로(함수객체):
    return 함수객체

@그대로
def 합계(값들) -> int:
    return sum(값들)

def 자료(*값들):
    for 값 in 값들:
        yield 값

제곱 = lambda 값: 값 ** 2
원본 = {"기본": 5}
추가 = {"계산": int(sqrt(9))}
결과 = {**원본, **추가}
del 결과["기본"]

try:
    with 입출력.StringIO("9") as 스트림:
        if (읽음 := 스트림.read()):
            숫자 = int(읽음)
    if 숫자 > 5:
        raise ValueError("범위 초과")
except ValueError:
    숫자 = 제곱(결과["계산"])
finally:
    assert 결과["계산"] == 3

평가 = 숫자, 합계(자료(1, 2, 3)), 결과
